sqlEquivalent:
CREATE TABLE lab_categories (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_items (
  id SERIAL PRIMARY KEY,
  label VARCHAR(200) NOT NULL,
  category_id INTEGER NOT NULL REFERENCES lab_categories(id) ON DELETE CASCADE
);

starterCode:
// JavaScript track — same Prisma DSL
model LabCategory {
  id Int @id @default(autoincrement())
  name String
  items LabItem[]
  @@map("lab_categories")
}
model LabItem {
  id Int @id @default(autoincrement())
  label String
  categoryId Int @map("category_id")
  category LabCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)
  @@map("lab_items")
}

